package com.example.payment.architecturetest;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes;
import static com.tngtech.archunit.library.Architectures.layeredArchitecture;

import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.junit.AnalyzeClasses;
import com.tngtech.archunit.junit.ArchTest;
import com.tngtech.archunit.lang.ArchRule;

/**
 * Guards the module boundaries of the payment codebase so a technical detail
 * from the middle of the business code (application/domain) can never be
 * reached for directly by another layer, and dependencies only ever point
 * inward, toward the domain.
 *
 * <p>These run as "IT" tests bound to Maven's {@code verify} phase (see this
 * module's pom), not {@code test}, so they never slow down the fast
 * every-save unit test suite.
 */
@AnalyzeClasses(packages = "com.example.payment", importOptions = ImportOption.DoNotIncludeTests.class)
class LayeredArchitectureIT {

    private static final String DOMAIN = "Domain";
    private static final String APPLICATION = "Application";
    private static final String INFRASTRUCTURE = "Infrastructure";
    private static final String APP = "App";

    @ArchTest
    static final ArchRule layers_are_respected = layeredArchitecture()
            .consideringAllDependencies()
            .layer(DOMAIN).definedBy("com.example.payment.domain..")
            .layer(APPLICATION).definedBy("com.example.payment.application..")
            .layer(INFRASTRUCTURE).definedBy("com.example.payment.infrastructure..")
            .layer(APP).definedBy("com.example.payment.app..")

            .whereLayer(DOMAIN).mayOnlyBeAccessedByLayers(APPLICATION, INFRASTRUCTURE, APP)
            .whereLayer(APPLICATION).mayOnlyBeAccessedByLayers(INFRASTRUCTURE, APP)
            .whereLayer(INFRASTRUCTURE).mayOnlyBeAccessedByLayers(APP);

    @ArchTest
    static final ArchRule domain_stays_free_of_technical_frameworks = classes()
            .that().resideInAPackage("com.example.payment.domain..")
            .should().onlyDependOnClassesThat()
            .resideInAnyPackage("com.example.payment.domain..", "java..", "javax..");

    @ArchTest
    static final ArchRule application_stays_free_of_technical_frameworks = classes()
            .that().resideInAPackage("com.example.payment.application..")
            .should().onlyDependOnClassesThat()
            .resideInAnyPackage(
                    "com.example.payment.domain..",
                    "com.example.payment.application..",
                    "java..",
                    "javax..");

    public static void main(String[] args) {
        // Allows running the rules from an IDE without the ArchUnit runner.
        JavaClasses classes = new ClassFileImporter()
                .withImportOption(ImportOption.DoNotIncludeTests.INSTANCE)
                .importPackages("com.example.payment");
        layers_are_respected.check(classes);
        domain_stays_free_of_technical_frameworks.check(classes);
        application_stays_free_of_technical_frameworks.check(classes);
    }
}

